CREATE TABLE IF NOT EXISTS robo_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer',disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS robo_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS robo_sessions_user ON robo_sessions(user_id);
CREATE TABLE IF NOT EXISTS robo_login_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,reset INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS robo_subscriptions(user_id TEXT PRIMARY KEY,plan TEXT NOT NULL,expires INTEGER NOT NULL,message_limit INTEGER NOT NULL,message_count INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS robo_payments(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,admin_id TEXT NOT NULL,reference TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL,plan TEXT NOT NULL,days INTEGER NOT NULL,message_limit INTEGER NOT NULL,created INTEGER NOT NULL);
